      {
        "ballot_id": "B034",
        "laureates": [
          "Hidetoshi Katori",
          "Jun Ye"
        ],
        "citation": "For the invention and realization of optical lattice clocks."
      }
    ]
  },
  "alternatives": [
    "B001",
    "B058"
  ],
  "statement": {
    "case_for": "Optical lattice clocks turned optical frequency measurement into a stable, exceptionally precise tool by controlling atomic motion while preserving narrow clock transitions. Katori's concept and Ye's experimental advances established complementary foundations for a method that has been independently realized and repeatedly improved. Its value is already scientific: precision comparisons test fundamental physics as well as improve timekeeping.",
    "case_against": "The field continues to advance, and its most consequential tests may still be emerging. The committee would need to define the recognized invention carefully and consider whether other clock pioneers belong within its historical boundary.",
    "responses": [
      {
        "member_id": "kroll-stefan",
        "point": "Kroll finds the two-person attribution persuasive but notes that the boundary between the core invention and later clock generations could change how broadly credit is assigned.",
        "response": "I agree that the citation should be anchored to the optical lattice clock concept and its realization, rather than to every later improvement in clock performance. That framing supports Katori and Ye while leaving the historical record of the first demonstrations to be checked carefully."
      },
      {
        "member_id": "eriksson-olle",
        "point": "Eriksson recognizes Katori and Ye's complementary contributions but cautions that the technology's full long-term scientific impact is still unfolding.",
        "response": "That uncertainty matters, but the case need not rest on future applications or a completed program of fundamental tests. The clocks have already enabled robust, exceptionally precise measurement across laboratories; the core achievement is a mature new measurement method."
      }
    ],
    "uncertainties": [
      "The historical boundary between the original lattice-clock invention and subsequent advances by other groups needs careful review."
    ],
    "conflict_note": "My work is in superconducting circuits and I direct WACQT, creating a field-level connection to B058 that may warrant review under recusal rules."
  }
}
